// render-codex-gitignore.mjs: renders codex/.gitignore, the allowlist that
// decides which of codex/'s files git tracks. It was hand-authored until
// 2026-09-17, and the failure mode that ended that was silent: a new skill
// under claude/skills/ was generated into codex/skills/<name>/SKILL.md,
// matched the leading `*`, was never named back in, and so stayed untracked
// while `--check` exited 0, because check compares content and knows nothing
// about git. The port lost a file and nothing said so. Deriving the list from
// the planned tree makes that impossible: a generated file that is not in the
// allowlist is now a stale .gitignore, which is a --check failure in CI and
// at push. Same lesson as sync.sh's retired exclude list, in reverse: a
// hand-typed list that must be exhaustive to be correct is the wrong shape.
const GITIGNORE_PATH = ".gitignore";

const HEADER_LINES = [
  "# GENERATED by translate/codex.mjs from the planned codex/ tree. Do not edit;",
  "# add or remove a claude/ source, or a hand_authored entry in",
  "# translate/codex-port-map.json, then run: node translate/codex.mjs --write",
  "#",
  "# An allowlist, not a denylist: everything under codex/ is ignored, then every",
  "# generated and hand-authored file is named back in, so a generated file can no",
  "# longer go missing from git for want of a hand edit.",
  "#",
  "# Nothing else belongs in this directory. --write deletes any file it did not",
  "# plan and removes the directories those deletions empty, so keep no scratch,",
  "# no local state and no notes here; an OS artifact such as .DS_Store will fail",
  "# --check until the next --write sweeps it.",
];

// renderGitignore(trackedPaths, portMap) -> { path: ".gitignore", content }:
// `*` followed by one `!/<path>` per tracked file and one `!/<dir>/` per
// ancestor directory of each, sorted byte-wise so the output is
// deterministic. trackedPaths is every generated path (the caller adds the
// manifest's own path, which is planned after this file); the port map's
// hand_authored entries and this file itself are added here, since no
// caller should have to remember that an allowlist must list itself.
export function renderGitignore(trackedPaths, portMap) {
  const entries = new Set();
  for (const filePath of [...trackedPaths, GITIGNORE_PATH, ...portMap.hand_authored]) {
    entries.add(filePath);
    // Every ancestor directory needs its own negation. Git does not descend
    // into an ignored directory, so `!/skills/name/SKILL.md` on its own never
    // matches: the walk stops at `skills/`. Paths here are always
    // forward-slash (the renderers build them from template strings, not from
    // path.join), which is also the only separator .gitignore syntax accepts.
    const segments = filePath.split("/");
    for (let depth = 1; depth < segments.length; depth += 1) {
      entries.add(`${segments.slice(0, depth).join("/")}/`);
    }
  }
  const negations = [...entries].sort().map((entry) => `!/${entry}`);
  return { path: GITIGNORE_PATH, content: `${[...HEADER_LINES, "*", ...negations].join("\n")}\n` };
}
